// startCallerSpan starts a real sampled span from an in-memory SDK and returns the
// context that carries it with the traceparent the span must produce.
func startCallerSpan(t *testing.T, parent context.Context) (context.Context, string) {
	t.Helper()
	provider := sdktrace.NewTracerProvider(
		sdktrace.WithSyncer(tracetest.NewInMemoryExporter()),
		sdktrace.WithSampler(sdktrace.AlwaysSample()),
	)
	t.Cleanup(func() { _ = provider.Shutdown(context.Background()) })
	ctx, span := provider.Tracer("trace-context-test").Start(parent, "caller")
	t.Cleanup(func() { span.End() })
	sc := span.SpanContext()
	return ctx, "00-" + sc.TraceID().String() + "-" + sc.SpanID().String() + "-" + sc.TraceFlags().String()
}

