// rotatingAuth hands out a new Authorization value every time it is asked.
type rotatingAuth struct {
	baseApiAuth
	calls atomic.Int32
}

func (a *rotatingAuth) AuthHeaders() map[string]string {
	return map[string]string{"Authorization": "Bearer t" + string(rune('0'+a.calls.Add(1)))}
}

